"""The fixed answers to the conflicts a `brockit rebase` stops on.

Rebasing a `cr` branch stops on the same kinds of conflicts every time, and
most of them have an answer that needs no judgement. Each `Rule` knows one of
these answers:

* `PLASTER` -- a patch managed by plaster is regenerated by rerunning its
  plaster.
* `CODEHEALTH_TRACKER` -- a CodeHealth tracker the base doesn't have is the
  branch's own, so the branch's last version of it is taken.
* `VERSION_BUMP` -- the version commit takes the newer Chromium tag and
  pinslist timestamp, when the base moved on to a newer minor version.
* `CONTEXT_ONLY_PATCH` -- a raw patch that the base changed only in its context
  takes the commit's version.

`ConflictedStep.resolve` runs the rules over the conflicted files of a stop,
and writes each answer into the working tree. Staging the answers and continuing
the rebase is left to the caller (`brockit.Rebase`).
"""

from __future__ import annotations

from dataclasses import dataclass
import enum
import functools
import logging
from pathlib import Path
import re
import subprocess
from typing import Callable

import patchfile
import plaster
import rebase
import repository
import versioning
from versioning import Version

# The CodeHealth tracker for a milestone, e.g. `tools/cr/M158_codehealth.md`.
_CODEHEALTH_TRACKER_RE = re.compile(r'tools/cr/M\d+_codehealth\.md')

# The `package.json` line with the Chromium tag (`projects.chrome.tag`), the
# only `tag` key in the file.
_CHROME_TAG_LINE_RE = re.compile(
    r' *"tag": "(?P<version>\d+\.\d+\.\d+\.\d+)",?\n'
)

# A conflicting hunk, as git writes it into the working tree. The section
# opened by `|||||||` holds the ancestor's lines, and is only there with the
# `diff3` and `zdiff3` conflict styles.
_CONFLICT_HUNK_RE = re.compile(
    r'^<{7}(?: .*)?\n'
    r'(?P<rebased>(?:.*\n)*?)'
    r'(?:\|{7}(?: .*)?\n(?:.*\n)*?)?'
    r'={7}\n'
    r'(?P<commit>(?:.*\n)*?)'
    r'>{7}(?: .*)?\n',
    re.MULTILINE,
)


class Stage(enum.IntEnum):
    """The versions git keeps of a conflicted file, by index stage number.

    Git calls the base being rebased onto "ours" during a rebase, which reads
    backwards, so these are named after what they hold instead.
    """

    # The file in the parent of the commit being applied.
    ANCESTOR = 1

    # The file as rebased so far: the base, plus the commits already applied.
    REBASED = 2

    # The file in the commit being applied.
    COMMIT = 3


class Rule(enum.Enum):
    """The fixed answers, in the order they are tried on a conflicted file.

    Each value heads the files the rule resolved in the rebase report.
    """

    PLASTER = 'Patches regenerated from their plaster'
    CODEHEALTH_TRACKER = (
        "CodeHealth trackers taken from the branch's last version"
    )
    VERSION_BUMP = 'Version bumps settled on the newer version'
    CONTEXT_ONLY_PATCH = (
        'Raw patches taken from the commit, as the base only moved their '
        'context (candidates for conversion to plaster)'
    )


@dataclass(frozen=True)
class Resolution:
    """A conflicted file a rule resolved."""

    # The file, relative to the brave root.
    path: str

    # The rule that resolved it.
    rule: Rule


@dataclass(frozen=True)
class ConflictedStep:
    """A rebase stopped on a commit that did not apply cleanly."""

    # The commit being applied, and its subject.
    commit: str
    subject: str

    # The commit the branch is being rebased onto, and the branch's tip from
    # before the rebase.
    onto: str
    orig_head: str

    # The conflicted files, relative to the brave root.
    paths: tuple[str, ...]

    @staticmethod
    def load() -> ConflictedStep | None:
        """Returns the step the rebase in progress stopped on.

        Returns None when nothing is conflicted, e.g. when the rebase stopped
        on an `edit`, or when every conflict has already been resolved and
        staged.
        """
        brave = repository.brave
        paths = brave.run_git(
            'diff', '--name-only', '--diff-filter=U'
        ).splitlines()
        if not paths:
            return None

        # Git records where the rebase started from in its state directory.
        state_dir = brave.rebase_merge_dir()
        return ConflictedStep(
            commit=brave.run_git('rev-parse', 'REBASE_HEAD'),
            subject=brave.get_commit_short_description('REBASE_HEAD'),
            onto=_read_commit_file(state_dir / 'onto'),
            orig_head=_read_commit_file(state_dir / 'orig-head'),
            paths=tuple(paths),
        )

    def read(self, path: str, stage: Stage) -> str | None:
        """Returns the `stage` version of a conflicted file.

        Returns None when there is no such version, e.g. for the side of a
        conflict that deleted the file.
        """
        try:
            return repository.brave.read_file(path, commit=f':{stage.value}')
        except subprocess.CalledProcessError:
            return None

    @functools.cached_property
    def _chromium_in_sync(self) -> bool:
        """Whether the Chromium checkout is on the version rebased so far.

        That is the version a patch belongs to at this point of the rebase,
        e.g. the branch's own once its version commit is in. Warns, once per
        stop, when the checkout is on another version.
        """
        rebased = Version.from_git('HEAD')
        checkout = versioning.read_chromium_version_file()
        if checkout != rebased:
            logging.warning(
                'Chromium is checked out at %s, but the rebase is at %s, so '
                'no patch is regenerated from its plaster.',
                checkout,
                rebased,
            )
        return checkout == rebased

    def resolve(self) -> list[Resolution]:
        """Resolves the conflicted files that a rule has an answer for.

        The answers are written into the working tree, without staging them.
        Files that no rule has an answer for are left untouched.
        """
        # The answer each rule gives for a file, written into the working
        # tree when it has one.
        resolvers: dict[Rule, Callable[[str], bool]] = {
            Rule.PLASTER: self._regenerate_from_plaster,
            Rule.CODEHEALTH_TRACKER: self._take_branch_codehealth_tracker,
            Rule.VERSION_BUMP: self._settle_version_bump,
            Rule.CONTEXT_ONLY_PATCH: self._take_commit_raw_patch,
        }
        resolutions = []
        for path in self.paths:
            rule = next((rule for rule in Rule if resolvers[rule](path)), None)
            if rule is not None:
                resolutions.append(Resolution(path=path, rule=rule))
        return resolutions

    def _regenerate_from_plaster(self, path: str) -> bool:
        """Regenerates a conflicted patch by rerunning its plaster.

        A plaster that is conflicted too has to be settled first, so its patch
        is left alone. The patch is regenerated against the Chromium checkout,
        so it is also left alone unless the checkout is on the version rebased
        so far.
        """
        plaster_file = patchfile.plaster_path_for_patch(Path(path))
        if plaster_file is None:
            return False
        plaster_path = repository.brave.to_repo_relative(plaster_file)
        if plaster_path.as_posix() in self.paths:
            return False
        if not self._chromium_in_sync:
            return False
        try:
            plaster.PlasterFile(plaster_file).apply()
        except (plaster.PlasterError, ValueError):
            # A plaster that no longer applies has to be fixed by hand.
            return False
        return True

    def _take_branch_codehealth_tracker(self, path: str) -> bool:
        """Takes the branch's last version of a CodeHealth tracker.

        This only applies to a tracker the base doesn't have, which is the
        branch's own. Such a tracker only conflicts because the rebase reorders
        the branch's commits (e.g. moving pinned commits to the top), and the
        branch's last version of it is where those commits lead. The tracker is
        a document, so it doesn't matter that the commits in between see that
        last version.
        """
        if not _CODEHEALTH_TRACKER_RE.fullmatch(path):
            return False
        if _has_file(self.onto, path) or not _has_file(self.orig_head, path):
            return False
        repository.brave.run_git('checkout', self.orig_head, '--', path)
        return True

    def _settle_version_bump(self, path: str) -> bool:
        """Settles the version commit's conflict over the version bump itself.

        When the base moved on to a newer minor version, the version commit
        conflicts on what both bumped: the Chromium tag in `package.json`, and
        the pinslist timestamp. The answer is the commit's Chromium tag,
        provided it is newer than the base's, and the newer of the two
        timestamps. A file is only settled when that is its single conflicting
        hunk, as anything else conflicting in it needs a look.
        """
        if rebase.get_pinned_group_for_subject(self.subject) != 'version':
            return False
        choose = _VERSION_BUMP_CHOICES.get(path)
        if choose is None:
            return False

        file = repository.brave.root / path
        conflict = _SingleConflict.parse(file.read_bytes().decode('utf-8'))
        if conflict is None:
            return False
        side = choose(conflict)
        if side is None:
            return False
        file.write_text(conflict.resolve(side), encoding='utf-8', newline='')
        return True

    def _take_commit_raw_patch(self, path: str) -> bool:
        """Takes the commit's version of a raw patch the base only re-anchored.

        When the base changed a raw patch (one without a plaster) only in its
        context, and not in the lines the patch adds or removes, the base only
        regenerated it for its own Chromium version. The commit's version is
        the same patch regenerated for the commit's Chromium version, so it is
        the answer. Patches like these are candidates for conversion to
        plaster, which would regenerate them on its own.
        """
        if not path.startswith('patches/') or not path.endswith('.patch'):
            return False
        if patchfile.patch_has_plaster(Path(path)):
            return False

        ancestor = self.read(path, Stage.ANCESTOR)
        rebased = self.read(path, Stage.REBASED)
        if ancestor is None or rebased is None:
            return False
        if self.read(path, Stage.COMMIT) is None:
            return False
        if _changed_lines(rebased) != _changed_lines(ancestor):
            return False

        # In a rebase, `--theirs` is the commit being applied.
        repository.brave.run_git('checkout', '--theirs', '--', path)
        return True


@dataclass(frozen=True)
class _SingleConflict:
    """The text of a file with a single conflicting hunk, split around it."""

    # The text before and after the hunk.
    before: str
    after: str

    # The two sides of the hunk: as rebased so far, and as in the commit being
    # applied.
    rebased: str
    commit: str

    @staticmethod
    def parse(text: str) -> _SingleConflict | None:
        """Splits `text` around its conflicting hunk.

        Returns None unless `text` has exactly one conflicting hunk.
        """
        hunks = list(_CONFLICT_HUNK_RE.finditer(text))
        if len(hunks) != 1:
            return None
        [hunk] = hunks
        return _SingleConflict(
            before=text[: hunk.start()],
            after=text[hunk.end() :],
            rebased=hunk['rebased'],
            commit=hunk['commit'],
        )

    def resolve(self, side: str) -> str:
        """Returns the text with the hunk replaced by `side`."""
        return f'{self.before}{side}{self.after}'


def _commit_chrome_tag(conflict: _SingleConflict) -> str | None:
    """Picks the commit's side of a conflict over the Chromium tag.

    Returns None unless each side is just the Chromium tag, and the commit's is
    the newer one.
    """
    rebased = _CHROME_TAG_LINE_RE.fullmatch(conflict.rebased)
    commit = _CHROME_TAG_LINE_RE.fullmatch(conflict.commit)
    if rebased is None or commit is None:
        return None
    if Version(commit['version']) <= Version(rebased['version']):
        return None
    return conflict.commit


def _newer_pinslist_timestamp(conflict: _SingleConflict) -> str | None:
    """Picks the side of a conflict over the pinslist timestamp that is newer.

    Returns None unless each side is just the pinslist timestamp block.
    """
    rebased = versioning.PINSLIST_TIMESTAMP_RE.fullmatch(conflict.rebased)
    commit = versioning.PINSLIST_TIMESTAMP_RE.fullmatch(conflict.commit)
    if rebased is None or commit is None:
        return None
    if int(commit['timestamp']) > int(rebased['timestamp']):
        return conflict.commit
    return conflict.rebased


# How the version commit's conflict is settled in each of the files it bumps.
_VERSION_BUMP_CHOICES: dict[str, Callable[[_SingleConflict], str | None]] = {
    versioning.PACKAGE_FILE: _commit_chrome_tag,
    versioning.PINSLIST_TIMESTAMP_FILE: _newer_pinslist_timestamp,
}


def _changed_lines(patch: str) -> list[str]:
    """The lines a patch adds and removes, without its headers or context."""
    changed = []
    in_hunk = False
    for line in patch.splitlines():
        if line.startswith('diff --git '):
            in_hunk = False
        elif line.startswith('@@ '):
            in_hunk = True
        elif in_hunk and line.startswith(('+', '-')):
            changed.append(line)
    return changed


def _has_file(commit: str, path: str) -> bool:
    """Whether `path` exists in `commit`."""
    try:
        repository.brave.run_git('cat-file', '-e', f'{commit}:{path}')
    except subprocess.CalledProcessError:
        return False
    return True


def _read_commit_file(file: Path) -> str:
    """Reads a commit hash from one of git's state files."""
    return file.read_bytes().decode('utf-8').strip()
